typedef float rational_t;
typedef float time_value_t;

enum device_id_t { JOYSTICK_DEVICE = 1 };
enum { PLAYER_FRONT_CROUCH = 26 };
static const float AXIS_MAX = 1.0f;
static const float PI = 3.14159265358979323846f;

class vector3d {
public:
  float x, y, z;
  vector3d(float _x, float _y, float _z) : x(_x), y(_y), z(_z) {}
};

class orientation { float m[16]; };
class po {
public:
  float m[16];
  void set_rot(const vector3d &, rational_t);
  orientation get_orientation() const;
};
po operator*(const po &, const po &);

class input_mgr {
public:
  static input_mgr *inst();
  rational_t get_control_state(device_id_t, int) const;
};

class entity {
public:
  void set_rel_orientation(const orientation &);
};

class motion_object {
  bool active;
  bool locked;
public:
  virtual ~motion_object();
};
class motion_control_system : public motion_object {
public:
  virtual ~motion_control_system();
  virtual void frame_advance(time_value_t) = 0;
protected:
  entity *ent;
};
class theta_and_psi_mcs : public motion_control_system {
public:
  virtual ~theta_and_psi_mcs();
  virtual void frame_advance(time_value_t);
private:
  rational_t theta;
  rational_t psi;
  rational_t d_theta_for_next_frame;
  rational_t d_psi_for_next_frame;
};

extern vector3d up_vector;

void theta_and_psi_mcs::frame_advance(time_value_t time_inc)
{
  if (input_mgr::inst()->get_control_state( JOYSTICK_DEVICE, PLAYER_FRONT_CROUCH) < 2*AXIS_MAX/3 )
  {
    theta += d_theta_for_next_frame;
    psi += d_psi_for_next_frame;

    if (psi < -PI*0.5f) psi = -PI*0.5f;
    else if (psi > PI*0.5f) psi = PI*0.5f;

    po rotate_around_y;
    rotate_around_y.set_rot( up_vector, theta );
    po rotate_around_x;
    rotate_around_x.set_rot( vector3d(1,0,0), psi );
    po rotate_around = rotate_around_x * rotate_around_y;
    ent->set_rel_orientation( rotate_around.get_orientation() );
  }
}
